CREATE TABLE IF NOT EXISTS chats (chat_id TEXT PRIMARY KEY,home_group TEXT NOT NULL DEFAULT '2.2',water_group TEXT NOT NULL DEFAULT '1.2',timezone TEXT NOT NULL DEFAULT 'Europe/Kyiv',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS schedules (id INTEGER PRIMARY KEY AUTOINCREMENT,chat_id TEXT NOT NULL,schedule_date TEXT NOT NULL,group_name TEXT NOT NULL,mode TEXT NOT NULL CHECK(mode IN ('off','on')),intervals_json TEXT NOT NULL,source_text TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(chat_id,schedule_date,group_name));
CREATE TABLE IF NOT EXISTS water_rules (chat_id TEXT PRIMARY KEY,fallback_intervals_json TEXT NOT NULL,source_text TEXT,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
